 useEffect(()=>{onDirtyChange?.(dirty)},[dirty]);
 useEffect(()=>{if(complete||!refresh)return;const id=setInterval(()=>{const s=sync.current;if(!s.busy&&!s.dirty&&!s.capture)void s.refresh?.()},15000);return()=>clearInterval(id)},[complete,!!refresh]);
 const step=complete||m.status==='Planned'?localStep:initialStep||m.agendaStep||'Segue',index=Math.max(0,l10Agenda.findIndex(a=>a.name===step)),agenda=l10Agenda[index];
