 const issueRows=review?.issues||[],visibleIssues=issueRows.filter((r:any)=>issueFilter==='All'||(issueFilter==='Solved'?r.status==='Solved':!['Solved','Archived'].includes(r.status))),issue=visibleIssues.find((r:any)=>r.id===issueId)||visibleIssues[0],currentIssue=issue?record(issue.id):undefined;
